{
  "IP": "neorv32_sdi",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "SDI transmit data",
      "Unit": "neorv32_sdi",
      "Information": "The byte written by the host to the transmit path and shifted out on SDI; serial transmission depends on preserving this data.",
      "Rubric": {
        "Confidentiality": "yes",
        "Integrity": "yes",
        "Availability": "no",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Confidentiality is at risk because the data reaches the externally visible sdi_dat_o at line 345 after entering the transmit path at line 201. Integrity is at risk because the transmit byte is loaded and shifted through serial.sreg at lines 305 and 327, where an internal fault or attack could alter it.",
      "Objectives At Risk": [
        "C",
        "I"
      ],
      "Attack": "An attacker could alter the bus write data or the transmit shift path so that a different byte is sent on sdi_dat_o, or observe the transmitted byte.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "sdi_dat_o"
      ],
      "Entry Lines": [
        201
      ],
      "Held Lines": [],
      "Exit Lines": [
        345
      ]
    },
    {
      "Concept ID": "C2",
      "Concept Name": "SDI receive data",
      "Unit": "neorv32_sdi",
      "Information": "The byte sampled from SDI and returned to the host through the receive path; software depends on receiving the sampled serial data correctly.",
      "Rubric": {
        "Confidentiality": "yes",
        "Integrity": "yes",
        "Availability": "no",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Confidentiality is at risk because sampled data enters from sdi_dat_i at line 270 and can be exposed through bus_rsp_o.data at line 162. Integrity is at risk because the sampled bit is captured into serial.sdi_ff and shifted into serial.sreg at lines 314 and 327 before being written to the receive FIFO at line 235.",
      "Objectives At Risk": [
        "C",
        "I"
      ],
      "Attack": "An attacker could corrupt the sampled-bit or receive path so that software reads a modified byte from bus_rsp_o.data, or observe the received byte at the read-back interface.",
      "Enters Through": [
        "sdi_dat_i"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        270
      ],
      "Held Lines": [],
      "Exit Lines": [
        162
      ]
    },
    {
      "Concept ID": "C3",
      "Concept Name": "SDI operational enable state",
      "Unit": "neorv32_sdi",
      "Information": "The run-time enable state that permits SDI operation and controls whether the transmit and receive FIFOs remain active; bus configuration and serial operation depend on it.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity is at risk because a bus write assigns ctrl.enable from bus_req_i.data at line 133. Availability is at risk because ctrl.enable clears both FIFOs at lines 200 and 239, controls the serial state at line 296, and gates the interrupt behavior at line 249.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could write the enable control to disable the interface and clear queued transmit or received data, or alter it during operation to disrupt transfers.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        133
      ],
      "Held Lines": [
        117,
        133
      ],
      "Exit Lines": [
        143
      ]
    },
    {
      "Concept ID": "C4",
      "Concept Name": "SDI transaction framing",
      "Unit": "neorv32_sdi",
      "Information": "The SDI chip-select and transaction-framing state indicating whether a serial transaction is active; the serial engine starts, advances, or terminates transfers based on it.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity is at risk because the synchronized chip-select controls transaction start and termination at lines 307, 315, and 324 and its active state is reported at line 160. Availability is at risk because the serial engine can block or terminate processing when the chip-select conditions at lines 307, 315, and 324 are not met.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could cause the chip-select framing path to be misinterpreted, making the engine start, terminate, or withhold a serial transfer at the wrong time.",
      "Enters Through": [
        "sdi_csn_i"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        269
      ],
      "Held Lines": [],
      "Exit Lines": [
        160
      ]
    },
    {
      "Concept ID": "C5",
      "Concept Name": "Interrupt request condition",
      "Unit": "neorv32_sdi",
      "Information": "The interrupt request condition reported to the integrating system when enabled receive or transmit FIFO conditions occur; system servicing behavior can depend on this event.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity is at risk because irq_o is produced from the enable, interrupt conditions, and FIFO status at lines 249 through 254, so an internal fault can create a false or missing request. Availability is at risk because the same logic can suppress the interrupt request, preventing the integrating system from servicing the interface.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could manipulate the interrupt-generation inputs or logic so that required receive or transmit service is not requested, or spurious interrupts are generated.",
      "Enters Through": [],
      "Leaves Through": [
        "irq_o"
      ],
      "Entry Lines": [],
      "Held Lines": [
        247,
        249
      ],
      "Exit Lines": [
        249
      ]
    }
  ],
  "Not Kept": [
    {
      "Candidate Name": "Interrupt-enable configuration",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The fields at lines 135 through 139 only tune the interrupt request output and its read-back, so the Port options rule bars them as a separate conceptual asset."
    },
    {
      "Candidate Name": "FIFO occupancy and buffer status",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The availability, half-full, free, and empty indicators at lines 153 through 158 and 250 through 254 only report or control buffered data and interrupt signaling, so the buffer and engine status rules bar them as separate pieces."
    },
    {
      "Candidate Name": "Serial engine sequencing state",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "serial.state, serial.cnt, serial.start, and serial.done at lines 286 through 340 only sequence and pace movement of serial data, so the Sequencing state rule bars them as independent information."
    },
    {
      "Candidate Name": "Input synchronizer state",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The synchronizer pipeline at lines 264 through 276 only resamples the serial clock, chip-select, and data inputs, so its stages are working copies rather than conceptual assets."
    },
    {
      "Candidate Name": "Bus access handshake and command fields",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The acknowledge, error, strobe, direction, and register-selection behavior at lines 125 through 142, 202, and 240 is covered by the bus-handshake and access-command rules rather than forming separate information pieces."
    },
    {
      "Candidate Name": "FIFO-size build configuration",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "RTX_FIFO only fixes the FIFO build at lines 20 and 176 through 180 and cannot be changed or withheld at run time, so the Build-time values rule excludes it."
    },
    {
      "Candidate Name": "Clock and reset signals",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "clk_i, rstn_i, and the serial clock input only time or reset the design, as shown at lines 23, 24, 268, and 283, and are excluded by the clock and reset rules."
    }
  ],
  "Notes": []
}
